using Microsoft.EntityFrameworkCore;
using PedeLocal.Application.Common;
using PedeLocal.Application.Common.Exceptions;
using PedeLocal.Application.Common.Interfaces;
using PedeLocal.Contracts.Common;
using PedeLocal.Contracts.Inventory;
using PedeLocal.Domain.Audit;
using PedeLocal.Domain.Catalog;
using PedeLocal.Domain.Inventory;

namespace PedeLocal.Application.Inventory;

/// <summary>Manual stock adjustments a merchant can trigger. SALE and CANCELLATION_RESTORE
/// movements are system-generated by the Orders module and are never created here.</summary>
public class InventoryService(IAppDbContext db, ICurrentUserService currentUser, EstablishmentAccessGuard accessGuard)
{
    private static readonly InventoryMovementType[] AllowedManualTypes =
    [
        InventoryMovementType.Entry, InventoryMovementType.Loss, InventoryMovementType.Return, InventoryMovementType.Adjustment
    ];

    public async Task<InventoryMovementResponse> AdjustStockAsync(
        Guid establishmentId, Guid productId, AdjustStockRequest request, CancellationToken ct)
    {
        await accessGuard.EnsureAccessAsync(establishmentId, ct);

        if (!Enum.TryParse<InventoryMovementType>(request.Type, ignoreCase: true, out var type) || !AllowedManualTypes.Contains(type))
        {
            throw new AppException("INVALID_MOVEMENT_TYPE", "Tipo de movimentação inválido para ajuste manual.");
        }

        var product = await db.Products.SingleOrDefaultAsync(p => p.Id == productId && p.EstablishmentId == establishmentId, ct)
            ?? throw new NotFoundException("PRODUCT_NOT_FOUND", "Produto não encontrado.");

        if (product.StockMode != StockMode.Controlled)
        {
            throw new AppException("PRODUCT_NOT_STOCK_CONTROLLED", "Este produto não tem controle de estoque ativado.");
        }

        var previousQuantity = product.StockQuantity ?? 0;
        var newQuantity = type switch
        {
            InventoryMovementType.Entry or InventoryMovementType.Return => previousQuantity + request.Quantity,
            InventoryMovementType.Loss => previousQuantity - request.Quantity,
            // ADJUSTMENT sets stock to a known absolute value (e.g. after a manual count).
            InventoryMovementType.Adjustment => request.Quantity,
            _ => throw new AppException("INVALID_MOVEMENT_TYPE", "Tipo de movimentação inválido.")
        };

        if (newQuantity < 0)
        {
            throw new ConflictException("INSUFFICIENT_STOCK", "A movimentação resultaria em estoque negativo.");
        }

        product.StockQuantity = newQuantity;

        var movement = new InventoryMovement
        {
            ProductId = product.Id,
            Type = type,
            Quantity = request.Quantity,
            PreviousQuantity = previousQuantity,
            NewQuantity = newQuantity,
            UserId = currentUser.UserId,
            Reason = request.Reason
        };
        db.InventoryMovements.Add(movement);

        db.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId, Action = AuditActions.StockAdjusted,
            EntityType = nameof(Domain.Catalog.Product), EntityId = product.Id,
            MetadataJson = $"{{\"type\":\"{type}\",\"previousQuantity\":{previousQuantity},\"newQuantity\":{newQuantity}}}"
        });

        await db.SaveChangesAsync(ct);
        return ToResponse(movement);
    }

    public async Task<PagedResult<InventoryMovementResponse>> GetMovementsAsync(
        Guid establishmentId, Guid productId, PageRequest request, CancellationToken ct)
    {
        await accessGuard.EnsureAccessAsync(establishmentId, ct);

        if (!await db.Products.AnyAsync(p => p.Id == productId && p.EstablishmentId == establishmentId, ct))
        {
            throw new NotFoundException("PRODUCT_NOT_FOUND", "Produto não encontrado.");
        }

        return await db.InventoryMovements
            .Where(m => m.ProductId == productId)
            .OrderByDescending(m => m.CreatedAtUtc)
            .Select(m => ToResponse(m))
            .ToPagedResultAsync(request, ct);
    }

    private static InventoryMovementResponse ToResponse(InventoryMovement m) => new(
        m.Id, m.ProductId, m.Type.ToString(), m.Quantity, m.PreviousQuantity, m.NewQuantity, m.OrderId, m.UserId, m.Reason, m.CreatedAtUtc);
}
